package org.pocketlore.app;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.*;import org.json.*;
public final class NearbyTravelInstrumentation extends Instrumentation {
 JSONArray checks=new JSONArray(),cities=new JSONArray(),cards=new JSONArray();JSONObject result=new JSONObject();ScaleActivity activity;
 void ok(boolean v,String name){if(!v)throw new AssertionError(name);checks.put(name);}
 interface Checked {void run()throws Exception;}
 void rejects(Checked r,String label)throws Exception {boolean denied=false;try{r.run();}catch(Exception expected){denied=true;}ok(denied,label);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 void idle()throws Exception{long end=SystemClock.elapsedRealtime()+90000;while(activity.worker!=null&&activity.worker.isAlive()){if(SystemClock.elapsedRealtime()>end)throw new AssertionError("Worker timeout");Thread.sleep(50);}waitForIdleSync();}
 public void onStart(){Bundle b=new Bundle();try{
  activity=(ScaleActivity)startActivitySync(new Intent(getTargetContext(),ScaleActivity.class).putExtra("section","Places").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();
  JSONObject payload=ReviewedCities.load(activity);ScaleLibrary.Entry places=null;for(ScaleLibrary.Entry e:activity.library.entries())if(e.active&&e.kind().equals("places")){places=e;break;}ok(places!=null,"Real installed Places collection present");
  for(String name:new String[]{"Dubai","Abu Dhabi","Sharjah","London","Mexico City","Sydney"}){long start=SystemClock.elapsedRealtime();List<ScalePlaces.City> matches=ScalePlaces.cities(places,name,()->false);ok(!matches.isEmpty(),"Indexed city lookup "+name);cities.put(new JSONObject().put("query",name).put("matches",matches.size()).put("lookup_ms",SystemClock.elapsedRealtime()-start));
   for(ScalePlaces.City c:matches){JSONObject card=ReviewedCities.match(payload,c);if(card==null)continue;String text=ReviewedCities.render(payload,card,-1);ok(!text.contains(c.raw)&&!text.contains("asciiname")&&!text.contains("alternatenames"),"No complete row or unreviewed fields "+c.id);ok(text.contains("as is")&&text.contains("agency: unknown")&&text.contains("Section 8"),"Attribution and offline legal text "+c.id);
    for(int i=0;i<6;i++){JSONObject f=card.getJSONArray("fields").getJSONObject(i);String field=ReviewedCities.render(payload,card,i);ok(field.contains(f.getString("quote"))&&field.contains("["+f.getInt("start_utf16")+", "+f.getInt("end_utf16")+")"),"Displayed exact approved field "+c.id+"/"+f.getString("field"));}
    String raw=c.raw;c.raw+="x";rejects(()->ReviewedCities.match(payload,c),"Changed row denied "+c.id);c.raw=raw;String id=c.id;c.id="0";ok(ReviewedCities.match(payload,c)==null,"Wrong identity denied");c.id=id;
    JSONObject altered=new JSONObject(payload.toString());JSONArray list=altered.getJSONArray("cards");for(int n=0;n<list.length();n++)if(list.getJSONObject(n).getString("id").equals(c.id))list.getJSONObject(n).getJSONArray("fields").getJSONObject(0).put("start_utf16",1);rejects(()->ReviewedCities.match(altered,c),"Shifted span denied");
    JSONObject missing=new JSONObject(payload.toString());missing.put("license_html","");rejects(()->ReviewedCities.match(missing,c),"Missing license denied");
    runOnMainSync(()->{activity.category.setText("NoSuchCategoryForFrozenTravelControl");activity.nearby.search(c.lat,c.lon,c);});idle();ok(activity.results.getChildCount()==7,"Zero venues retains card and six field controls");
    final ScalePlaces.City selected=c;ActivityMonitor monitor=addMonitor(SourceReaderActivity.class.getName(),null,false);runOnMainSync(()->((Button)activity.results.getChildAt(0)).performClick());Activity reader=waitForMonitorWithTimeout(monitor,20000);removeMonitor(monitor);ok(reader instanceof SourceReaderActivity,"Actual reviewed city source reader "+c.id);
    long end=SystemClock.elapsedRealtime()+20000;while(((SourceReaderActivity)reader).entry==null&&SystemClock.elapsedRealtime()<end)Thread.sleep(50);NotebookStore.Entry entry=((SourceReaderActivity)reader).entry;ok(entry!=null&&entry.body.equals(text),"Actual source body equals approved projection");String portable=entry.portable();ok(!portable.contains(raw)&&portable.contains("Extractive"),"Notebook export excludes original raw row");Files.write(new File(getTargetContext().getFilesDir(),"city-export-"+c.id+".md").toPath(),portable.getBytes(StandardCharsets.UTF_8));cards.put(new JSONObject().put("id",c.id).put("rendered",text).put("portable_sha256",ReviewedCities.hash(portable)));runOnMainSync(reader::finish);waitForIdleSync();
   }
  }
  ok(cards.length()==3,"All three reviewed records inspected");ok(ScalePlaces.cities(places,"NoSuchCityForFrozenTravelControl",()->false).isEmpty(),"Absent city remains empty");
  rejects(()->NearbyTravel.coordinates(Double.NaN,0,1),"NaN rejected");rejects(()->NearbyTravel.coordinates(91,0,1),"Latitude range rejected");rejects(()->NearbyTravel.coordinates(0,0,101),"Radius range rejected");
  ok(NearbyTravel.dietEvidence(new JSONObject(),"vegan").equals("unknown"),"Absent diet tag never positive");ok(NearbyTravel.dietEvidence(new JSONObject("{tags:{'diet:vegan':'yes'}}"),"vegan").startsWith("Explicit saved"),"Constructed explicit tag parser control");
  runOnMainSync(()->activity.onRequestPermissionsResult(360,new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION},new int[]{android.content.pm.PackageManager.PERMISSION_DENIED}));ok(activity.status.getText().toString().contains("manually"),"Permission denial manual fallback");
  runOnMainSync(()->{activity.category.setText("");activity.radius.setText("2");activity.nearby.search(38.8895,-77.0353,null);});idle();ok(activity.results.getChildCount()>0,"Real dated DC source candidates from manual coordinates");result.put("manual_status",activity.status.getText());
  android.os.Debug.MemoryInfo mem=new android.os.Debug.MemoryInfo();android.os.Debug.getMemoryInfo(mem);result.put("pss_kib",mem.getTotalPss()).put("app_data_bytes",SharedShardUpdate.uniqueBytes(new File(getTargetContext().getApplicationInfo().dataDir))).put("status","PASS");
 }catch(Throwable e){try{result.put("status","FAIL").put("error",android.util.Log.getStackTraceString(e));}catch(Exception ignored){}}
 finally{if(activity!=null)runOnMainSync(activity::finish);try{result.put("checks",checks).put("cities",cities).put("cards",cards);Files.write(new File(getTargetContext().getFilesDir(),"nearby-travel.json").toPath(),result.toString(2).getBytes(StandardCharsets.UTF_8));b.putString("report",result.toString());}catch(Exception e){b.putString("error",e.toString());}finish(result.optString("status").equals("PASS")?-1:1,b);}}
}
